with target as(select * from public.works where id=any(array[]::bigint[]) or open_library_id=any(array['OL3698637W','OL3698639W','OL658274W','OL674108W','OL699558W','OL699559W','OL699562W','OL699564W','OL699565W','OL699569W']::text[]) or regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['nerveuzevertellingen','openbriefaanpltak','liefdesbrieven','deruinebouwer','brievenaanbernards19651975','brievenaanfransp19651969','brievenaanjosinem19591982','brievenaanludop19621980','brievenaanmatroosvosch19751992','brievenaanwimb19681975']::text[]) or id in(select work_id from public.catalog_work_title_aliases where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['nerveuzevertellingen','openbriefaanpltak','liefdesbrieven','deruinebouwer','brievenaanbernards19651975','brievenaanfransp19651969','brievenaanjosinem19591982','brievenaanludop19621980','brievenaanmatroosvosch19751992','brievenaanwimb19681975']::text[]))),a as(select * from public.authors where id in(select author_id from target) or open_library_id=any(array['OL641289A','OL51132A','OL52735A','OL55234A']::text[]) or regexp_replace(lower(normalize(name,NFD)),'[^a-z0-9]','','g')=any(array['jacobisraeldehaan','multatuli','eduarddouwesdekker','maxhavelaarmultatuli','eduarddouwesdekkerditmultatuli','jbernlef','hendrikjanmarsman','gerardkornelisvanhetreve','gerardreve']::text[])),e as(select * from public.editions where work_id in(select id from target) or open_library_edition_id=any(array['OL2898159M','OL14730216M','OL4521331M','OL4166223M','OL3880303M','OL2993560M','OL843096M','OL2309066M','OL287544M','OL2888179M']::text[]) or regexp_replace(coalesce(isbn_13,''),'[-[:space:]]','','g')=any(array['9789035100398','9789065211408','9789029532051','9789021451763','9789020403220','9789020409444','9789025409913','9789028205963','9789025422035','9789020403572']::text[])) select jsonb_build_object('project','qvplwejffhjvxaypmjut','checked_at',clock_timestamp(),'works',coalesce((select jsonb_agg(to_jsonb(t) order by id) from target t),'[]'),'authors',coalesce((select jsonb_agg(to_jsonb(t) order by id) from a t),'[]'),'author_corpora',coalesce((select jsonb_agg(to_jsonb(t) order by id) from public.works t where author_id in(select id from a)),'[]'),'editions',coalesce((select jsonb_agg(to_jsonb(t) order by id) from e t),'[]'),'metadata',coalesce((select jsonb_agg(to_jsonb(t) order by edition_id) from public.catalog_edition_metadata t where edition_id in(select id from e)),'[]'),'descriptions',coalesce((select jsonb_agg(to_jsonb(t) order by work_id,language) from public.catalog_work_descriptions t where work_id in(select id from target)),'[]'),'aliases',coalesce((select jsonb_agg(to_jsonb(t) order by work_id,title) from public.catalog_work_title_aliases t where work_id in(select id from target)),'[]')) as snapshot;
